# Generated by scripts/update-c0mpute.sh from the release's .sha256 files.
# The update-c0mpute workflow refreshes it when c0mpute publishes a release.
class C0mpute < Formula
  desc "Run a node on the c0mpute decentralized compute network"
  homepage "https://c0mpute.com"
  version "0.3.120"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/profullstack/c0mpute/releases/download/v0.3.120/c0mpute-darwin-aarch64.tar.gz"
      sha256 "5391b8bed53e1664f6a1156eeb3f94de1713ca64d67c2bc66a164b04c77a5ede"
    end
    on_intel do
      url "https://github.com/profullstack/c0mpute/releases/download/v0.3.120/c0mpute-darwin-x86_64.tar.gz"
      sha256 "bc809290118a7fd427a7a056051d7d6e90646073d9e47d86dc36d4768672f22f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/profullstack/c0mpute/releases/download/v0.3.120/c0mpute-linux-aarch64.tar.gz"
      sha256 "441e0ac4421c5babcd14ef963d48b2a24ada0576c92ab2021602186edb9e420a"
    end
    on_intel do
      url "https://github.com/profullstack/c0mpute/releases/download/v0.3.120/c0mpute-linux-x86_64.tar.gz"
      sha256 "7baec632339e3dcec57b06f32e505bcee2a8f365f5f6b2e770974070c93e3986"
    end
  end

  def install
    libexec.install "c0mpute"
    # Homebrew owns the binary, so turn off c0mpute's self-update;
    # `brew upgrade c0mpute` updates it instead.
    (bin/"c0mpute").write_env_script libexec/"c0mpute", C0MPUTE_NO_AUTO_UPDATE: "1"
  end

  def caveats
    <<~EOS
      Start a worker in the foreground, or in the background with -d:
        c0mpute worker start
        c0mpute worker start -d

      This formula installs the c0mpute CLI only. For the full node stack
      (coinpay and infernet CLIs, inference payouts), use the installer
      described at https://c0mpute.com (https://c0mpute.com/install.sh).

      Earnings depend on network demand and vary; see https://c0mpute.com/nodes
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/c0mpute --version")
  end
end
